def test_batch_delete(table: Table, container, mock_records):
    ids = [i["id"] for i in mock_records]
    with Mocker() as mock:
        for chunk in _chunk(ids, 10):
            json_response = {"records": [{"deleted": True, "id": id_} for id_ in chunk]}
            url_match = (
                Request("get", table.url, params={"records[]": chunk}).prepare().url
            )
            mock.delete(
                url_match,
                status_code=201,
                json=json_response,
            )

        resp = table.batch_delete(container(ids))
    expected = [{"deleted": True, "id": i} for i in ids]
    assert resp == expected

@pytest.mark.parametrize("op", ("AND", "OR"))
def test_compound(op):
    cmp = F.Compound(op, [EQ("foo", 1), EQ("bar", 2)])
    assert repr(cmp) == f"{op}(EQ('foo', 1), EQ('bar', 2))"

@pytest.mark.parametrize("op", ("AND", "OR"))
def test_compound_with_iterable(op):
    cmp = F.Compound(op, (EQ(f"f{n}", n) for n in range(3)))
    assert repr(cmp) == f"{op}(EQ('f0', 0), EQ('f1', 1), EQ('f2', 2))"

@pytest.mark.parametrize(
    "compound,expected",
    [
        (EQ(1, 1).eq(True), "(1=1)=TRUE()"),
        (EQ(False, EQ(1, 2)), "FALSE()=(1=2)"),
    ],
)
def test_compound_with_compound(compound, expected):
    assert str(compound) == expected

@pytest.mark.parametrize(
    "input,expected",
    [
        ("First Name", "{First Name}"),
        ("Guest's Name", r"{Guest\'s Name}"),
        ("With {Curly Braces}", r"{With {Curly Braces\}}"),
    ],
)
def test_field_name(input, expected):
    assert F.field_name(input) == expected

def test_quoted():
    assert F.quoted("John") == "'John'"
    assert F.quoted("Guest's Name") == "'Guest\\'s Name'"

def test_api_bases(api: Api, base_id: str, base_name: str, table_name: str):
    bases = {base.id: base for base in api.bases()}
    assert bases[base_id].name == base_name
    assert bases[base_id].table(table_name).name == table_name

def test_api_base(api: Api, base_id: str, base_name: str):
    base = api.base(base_id, validate=True)
    assert base.name == base_name

def test_audit_log(api):
    """
    Test that we can call the audit log endpoint.
    """
    if "AIRTABLE_ENTERPRISE_ID" not in os.environ:
        return pytest.skip("test_audit_log requires AIRTABLE_ENTERPRISE_ID")

    enterprise = api.enterprise(os.environ["AIRTABLE_ENTERPRISE_ID"])
    for page in enterprise.audit_log(page_limit=1):
        for event in page.events:
            assert isinstance(event.action, str)

def test_batch_upsert(table: Table, cols):
    one, two = table.batch_create(
        [
            {cols.TEXT: "One"},
            {cols.TEXT: "Two"},
        ]
    )

    # Test batch_upsert where replace=False
    result = table.batch_upsert(
        [
            {"id": one["id"], "fields": {cols.NUM: 3}},  # use id
            {"fields": {cols.TEXT: "Two", cols.NUM: 4}},  # use key_fields
            {"fields": {cols.TEXT: "Three", cols.NUM: 5}},  # create record
        ],
        key_fields=[cols.TEXT],
    )
    assert set(result["updatedRecords"]) == {one["id"], two["id"]}
    assert len(result["createdRecords"]) == 1
    assert len(result["records"]) == 3
    assert result["records"][0]["id"] == one["id"]
    assert result["records"][0]["fields"] == {cols.TEXT: "One", cols.NUM: 3}
    assert result["records"][1]["id"] == two["id"]
    assert result["records"][1]["fields"] == {cols.TEXT: "Two", cols.NUM: 4}
    assert result["records"][2]["fields"] == {cols.TEXT: "Three", cols.NUM: 5}

    # Test batch_upsert where replace=True
    result = table.batch_upsert(
        [
            {"id": one["id"], "fields": {cols.NUM: 3}},  # removes cols.TEXT
            {"fields": {cols.TEXT: "Two"}},  # removes cols.NUM
            {"fields": {cols.TEXT: "Three", cols.NUM: 6}},  # replaces cols.NUM
            {"fields": {cols.TEXT: None, cols.NUM: 7}},  # creates a record
        ],
        key_fields=[cols.TEXT],
        replace=True,
    )
    assert len(result["records"]) == 4
    assert result["records"][0]["id"] == one["id"]
    assert result["records"][0]["fields"] == {cols.NUM: 3}
    assert result["records"][1]["id"] == two["id"]
    assert result["records"][1]["fields"] == {cols.TEXT: "Two"}
    assert result["records"][2]["fields"] == {cols.TEXT: "Three", cols.NUM: 6}
    assert result["records"][3]["fields"] == {cols.NUM: 7}

    # Test that batch_upsert passes along use_field_ids
    result = table.batch_upsert(
        [{"fields": {cols.TEXT: "Two", cols.NUM: 8}}],
        key_fields=[cols.TEXT],
        use_field_ids=True,
    )
    assert result["records"] == [
        {
            "id": two["id"],
            "createdTime": two["createdTime"],
            "fields": {cols.TEXT_ID: "Two", cols.NUM_ID: 8},

def test_integration_attachment_multiple(table, cols, valid_img_url):
    rec = table.create(
        {
            cols.ATTACHMENT: [
                attachment(valid_img_url, filename="a.jpg"),
                attachment(valid_img_url, filename="b.jpg"),
            ]
        }
    )
    rv_get = table.get(rec["id"])
    assert rv_get["fields"]["attachment"][0]["filename"] == "a.jpg"
    assert rv_get["fields"]["attachment"][1]["filename"] == "b.jpg"
